scripts/Dpkg/BuildProfiles.pm:
my $profile_name_regex = qr{
    # Be lenient for now. Accept operators for extensibility, uppercase,
    # and package name characters.
    [
        ?/;:=@%*~_
        A-Z
        a-z0-9+.\-
    ]+
}x;

my $restriction_list_regex = qr{
    <
    \s*
    (
        !? $profile_name_regex
        (?:
            \s+
            !? $profile_name_regex
        )*
    )
    \s*
    >
}x;

my $restriction_formula_regex = qr{
    ^
    (?:
        \s*
        $restriction_list_regex
    )*
    \s*
    $
}x;

scripts/Dpkg/Email/Address.pm:
my $addr_name_regex = qr{
    # Composed of possibly multiple quoted and not-quoted parts.
    (?:
        # Either non-quoted name, without comma.
        [^<>"[:cntrl:],]+
    |
        # Or quoted name, with optional comma.
        " [^<>"[:cntrl:]]+ "
    )*
}xa;

my $addr_email_regex = qr{
    # Local part.
    [^@<>"\s[:cntrl:],]+
    # Separator.
    @
    # Domain part.
    [^@<>"\s[:cntrl:],]+
}xa;

my $addr_regex = qr{
    \s*
    # Address name.
    (
        $addr_name_regex
    )
    # Separated by at least one space.
    \s+
    # Address email in angle brackets.
    <
        (
            $addr_email_regex
        )
    >
    \s*
}x;

scripts/Dpkg/Email/AddressList.pm:
my $addr_regex = qr{example};

my $addrlist_elem_regex = qr{
    \s* $addr_regex (?: \s* , )*
}x;

my $addrlist_regex = qr{
    ^
    # Optional addresses separated by comma.
    (?: \s* $addr_regex (?: \s* , )+ )*

    # Required address followed by an optional trailing comma.
    (?: \s* $addr_regex ) (?: \s* , )*
    \s*
    $
}x;
